// Core tests: the 18 literal core cases from fixtures.json (expected
// values taken verbatim from the file, never generated by the product),
// plus hand-derived boundary, validation, and property cases from the
// SPEC. Every hand-derived expected value below was computed by hand
// from the SPEC's rules or by an independent high-precision
// recalculation (Decimal, 50 digits, true pi); the derivations are
// listed in AUTHOR-CHECK.md and in the comments below.

import assert from "node:assert/strict";
import test from "node:test";
import {
  formatDecimal,
  formatFillDuration,
  formatInteger,
  run,
} from "../public/js/core/pool-volume.mjs";
import fixtures from "./fixtures.json" with { type: "json" };

const coreCases = fixtures.cases.filter((entry) => entry.kind === "core");
for (const entry of coreCases) {
  test(`fixture ${entry.id}`, () => {
    assert.deepEqual(run(entry.input), entry.expected);
  });
}

const base = {
  shape: "rectangular",
  depthMode: "single",
  lengthM: "8",
  widthM: "4",
  diameterM: "5",
  depthM: "1.5",
  shallowDepthM: "1",
  deepDepthM: "2",
  flowRateLMin: "40",
};

function errorOf(input) {
  const outcome = run(input);
  assert.equal(outcome.ok, false);
  return outcome.error;
}

test("worked anchor: 2 x 3 x 1 m at 40 L/min is 6 m3, 6000 L, 1585 gal, 150 min", () => {
  // Hand-derived: V = 2 * 3 * 1 = 6 m3; 6000 L; 6000 / 3.785411784 =
  // 1585.0323... -> 1585; 6000 / 40 = 150 min = 2 h 30 min.
  const outcome = run({ ...base, lengthM: "2", widthM: "3", depthM: "1" });
  assert.equal(outcome.ok, true);
  assert.deepEqual(outcome.result, {
    shape: "rectangular",
    depthMode: "single",
    avgDepthM: 1,
    volumeM3: 6,
    volumeLitres: 6000,
    volumeGallonsUs: 1585,
    flowRateLMin: 40,
    fillTotalMinutes: 150,
    fillHours: 2,
    fillMinutes: 30,
  });
});

test("worked anchor: circular diameter 10, depth 2, flow 100", () => {
  // Hand-derived via the independent high-precision path: r = 5,
  // V = ((pi * 5) * 5) * 2 = 50 pi = 157.07963267948966... m3 ->
  // 157.08; litres 157079.632... -> 157080; gallons 157079.632... /
  // 3.785411784 = 41495.9... -> 41496; fill 157079.632... / 100 =
  // 1570.796... -> 1571 min = 26 h 11 min.
  const outcome = run({
    ...base,
    shape: "circular",
    diameterM: "10",
    depthM: "2",
    flowRateLMin: "100",
  });
  assert.equal(outcome.ok, true);
  assert.equal(outcome.result.avgDepthM, 2);
  assert.equal(outcome.result.volumeM3, 157.08);
  assert.equal(outcome.result.volumeLitres, 157080);
  assert.equal(outcome.result.volumeGallonsUs, 41496);
  assert.equal(outcome.result.fillTotalMinutes, 1571);
  assert.equal(outcome.result.fillHours, 26);
  assert.equal(outcome.result.fillMinutes, 11);
});

test("sloped with equal ends equals the single-depth result", () => {
  const sloped = run({ ...base, depthMode: "sloped", shallowDepthM: "1.5", deepDepthM: "1.5" });
  const single = run(base);
  assert.equal(sloped.ok, true);
  assert.equal(single.ok, true);
  assert.deepEqual(sloped.result, { ...single.result, depthMode: "sloped" });
});

test("flow rate 12.50 parses to 12.5 and empty flow rate nulls all four fill fields", () => {
  const parsed = run({ ...base, flowRateLMin: "12.50" });
  assert.equal(parsed.ok, true);
  assert.equal(parsed.result.flowRateLMin, 12.5);
  const empty = run({ ...base, flowRateLMin: "" });
  assert.equal(empty.ok, true);
  assert.equal(empty.result.flowRateLMin, null);
  assert.equal(empty.result.fillTotalMinutes, null);
  assert.equal(empty.result.fillHours, null);
  assert.equal(empty.result.fillMinutes, null);
});

test("boundary: dimensions 0.1 and 100, depth 0.1 and 10, flow 0.1 and 10000 all pass", () => {
  assert.equal(run({ ...base, lengthM: "0.1", widthM: "0.1", depthM: "0.1" }).ok, true);
  assert.equal(run({ ...base, lengthM: "100", widthM: "100", depthM: "10" }).ok, true);
  assert.equal(run({ ...base, flowRateLMin: "0.1" }).ok, true);
  assert.equal(run({ ...base, flowRateLMin: "10000" }).ok, true);
  assert.equal(run({ ...base, flowRateLMin: "10000.00" }).ok, true);
});

test("boundary: just over the limits is RANGE (101, 10.01, 10000.01, 0.09)", () => {
  assert.deepEqual(errorOf({ ...base, lengthM: "101" }), { code: "RANGE", field: "lengthM", row: null });
  assert.deepEqual(errorOf({ ...base, widthM: "101" }), { code: "RANGE", field: "widthM", row: null });
  assert.deepEqual(errorOf({ ...base, shape: "circular", diameterM: "101" }), {
    code: "RANGE",
    field: "diameterM",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, depthM: "10.01" }), { code: "RANGE", field: "depthM", row: null });
  assert.deepEqual(errorOf({ ...base, flowRateLMin: "10000.01" }), {
    code: "RANGE",
    field: "flowRateLMin",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, lengthM: "0.09" }), { code: "RANGE", field: "lengthM", row: null });
  assert.deepEqual(errorOf({ ...base, depthM: "0.09" }), { code: "RANGE", field: "depthM", row: null });
  assert.deepEqual(errorOf({ ...base, flowRateLMin: "0.09" }), {
    code: "RANGE",
    field: "flowRateLMin",
    row: null,
  });
  assert.deepEqual(
    errorOf({ ...base, depthMode: "sloped", shallowDepthM: "0.09", deepDepthM: "2" }),
    { code: "RANGE", field: "shallowDepthM", row: null },
  );
  assert.deepEqual(
    errorOf({ ...base, depthMode: "sloped", shallowDepthM: "1", deepDepthM: "10.01" }),
    { code: "RANGE", field: "deepDepthM", row: null },
  );
});

test("capacity: a 9-unit value is INPUT_LIMIT on every field, including inactive ones", () => {
  // shape allows 12, so 9 units of shape is not a limit error — it is
  // an enum error; a 13-unit shape is the limit case.
  assert.deepEqual(errorOf({ ...base, shape: "rectangularxx" }), {
    code: "INPUT_LIMIT",
    field: "shape",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, depthMode: "slopedxxx" }), {
    code: "INPUT_LIMIT",
    field: "depthMode",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, lengthM: "123456789" }), {
    code: "INPUT_LIMIT",
    field: "lengthM",
    row: null,
  });
  // Inactive diameter field: still capacity-checked in rectangular mode.
  assert.deepEqual(errorOf({ ...base, diameterM: "123456789" }), {
    code: "INPUT_LIMIT",
    field: "diameterM",
    row: null,
  });
  // Inactive shallow field: still capacity-checked in single mode.
  assert.deepEqual(errorOf({ ...base, shallowDepthM: "123456789" }), {
    code: "INPUT_LIMIT",
    field: "shallowDepthM",
    row: null,
  });
  // "rectangular" itself is 11 units and legal (limit 12).
  assert.equal(run({ ...base, shape: "rectangular" }).ok, true);
});

test("an inactive field is capacity-checked only and otherwise ignored", () => {
  // Arbitrary text in inactive fields is ignored entirely.
  assert.equal(run({ ...base, diameterM: "abc" }).ok, true);
  assert.equal(run({ ...base, shape: "circular", lengthM: "abc", widthM: "abc" }).ok, true);
  assert.equal(run({ ...base, shallowDepthM: "abc", deepDepthM: "abc" }).ok, true);
  assert.equal(run({ ...base, depthMode: "sloped", depthM: "abc" }).ok, true);
  // A lone surrogate in an inactive field is only capacity-checked
  // and passes (SPEC tests section; see HANDOFF.md errata candidate 1).
  assert.equal(run({ ...base, diameterM: "\uD800" }).ok, true);
  assert.equal(run({ ...base, shallowDepthM: "\uD800" }).ok, true);
});

test("an active field reports UNICODE before EMPTY and grammar", () => {
  assert.deepEqual(errorOf({ ...base, widthM: "\uD800" }), {
    code: "UNICODE",
    field: "widthM",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, shape: "\uD800" }), {
    code: "UNICODE",
    field: "shape",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, lengthM: "" }), { code: "EMPTY", field: "lengthM", row: null });
  assert.deepEqual(errorOf({ ...base, shape: "" }), { code: "EMPTY", field: "shape", row: null });
  assert.deepEqual(errorOf({ ...base, depthMode: "" }), {
    code: "EMPTY",
    field: "depthMode",
    row: null,
  });
  // Empty flow rate is legal (optional), not EMPTY.
  assert.equal(run({ ...base, flowRateLMin: "" }).ok, true);
});

test("decimal grammar: signs, exponents, commas, three decimals, trailing dot, leading dot and non-ASCII digits are DECIMAL_FORMAT", () => {
  for (const bad of ["-8", "+8", "1e3", "8,000", "8.125", "8.", ".5", "８", "8 "]) {
    assert.deepEqual(errorOf({ ...base, lengthM: bad }), {
      code: "DECIMAL_FORMAT",
      field: "lengthM",
      row: null,
    });
  }
  // Two decimals, trailing zeros and leading zeros are legal.
  assert.equal(run({ ...base, lengthM: "8.50", widthM: "4.00" }).ok, true);
  assert.equal(run({ ...base, lengthM: "08" }).ok, true);
  assert.equal(run({ ...base, lengthM: "100.00" }).ok, true);
});

test("enums: unknown shape and depthMode are ENUM; field order puts shape first", () => {
  assert.deepEqual(errorOf({ ...base, shape: "square" }), {
    code: "ENUM",
    field: "shape",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, depthMode: "average" }), {
    code: "ENUM",
    field: "depthMode",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, shape: "square", depthMode: "average" }), {
    code: "ENUM",
    field: "shape",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, lengthM: "bad", widthM: "bad" }), {
    code: "DECIMAL_FORMAT",
    field: "lengthM",
    row: null,
  });
});

test("depth order: shallow above deep is DEPTH_ORDER after all per-field checks", () => {
  assert.deepEqual(
    errorOf({ ...base, depthMode: "sloped", shallowDepthM: "2", deepDepthM: "1" }),
    { code: "DEPTH_ORDER", field: "deepDepthM", row: null },
  );
  // A per-field error wins over the cross-field rule.
  assert.deepEqual(
    errorOf({ ...base, depthMode: "sloped", shallowDepthM: "2", deepDepthM: "20" }),
    { code: "RANGE", field: "deepDepthM", row: null },
  );
  // Shallow equal to deep is legal.
  assert.equal(run({ ...base, depthMode: "sloped", shallowDepthM: "2", deepDepthM: "2" }).ok, true);
});

test("property: fill minutes are always 0-59 and hours/minutes recombine to the total", () => {
  for (const flow of ["1", "7", "13", "33", "40", "999", "10000"]) {
    const outcome = run({ ...base, flowRateLMin: flow });
    assert.equal(outcome.ok, true);
    const { fillTotalMinutes, fillHours, fillMinutes } = outcome.result;
    assert.ok(fillMinutes >= 0 && fillMinutes <= 59, `flow ${flow}`);
    assert.equal(fillHours * 60 + fillMinutes, fillTotalMinutes);
  }
});

test("property: litres never come from the displayed m3 (min-dimensions: 0 m3, 1 L)", () => {
  const outcome = run({ ...base, lengthM: "0.1", widthM: "0.1", depthM: "0.1", flowRateLMin: "" });
  assert.equal(outcome.ok, true);
  assert.equal(outcome.result.volumeM3, 0);
  assert.equal(outcome.result.volumeLitres, 1);
  assert.equal(outcome.result.volumeGallonsUs, 0);
});

test("property: volume never decreases as a dimension grows; fill time never increases as flow grows", () => {
  let previous = -Infinity;
  for (const length of ["1", "2", "4", "8", "16", "100"]) {
    const outcome = run({ ...base, lengthM: length });
    assert.equal(outcome.ok, true);
    assert.ok(outcome.result.volumeLitres >= previous);
    previous = outcome.result.volumeLitres;
  }
  previous = Infinity;
  for (const flow of ["1", "10", "40", "100", "1000", "10000"]) {
    const outcome = run({ ...base, flowRateLMin: flow });
    assert.equal(outcome.ok, true);
    assert.ok(outcome.result.fillTotalMinutes <= previous);
    previous = outcome.result.fillTotalMinutes;
  }
});

test("schema: extra key, missing key, wrong type, array, null, accessor and symbol key are all SCHEMA", () => {
  const schema = { code: "SCHEMA", field: null, row: null };
  assert.deepEqual(errorOf({ ...base, extra: "1" }), schema);
  const missing = { ...base };
  delete missing.flowRateLMin;
  assert.deepEqual(errorOf(missing), schema);
  assert.deepEqual(errorOf({ ...base, lengthM: 8 }), schema);
  assert.deepEqual(errorOf({ ...base, flowRateLMin: null }), schema);
  assert.deepEqual(errorOf(["rectangular"]), schema);
  assert.deepEqual(errorOf(null), schema);
  assert.deepEqual(errorOf("rectangular"), schema);
  const withGetter = { ...base };
  Object.defineProperty(withGetter, "lengthM", {
    enumerable: true,
    get() {
      return "8";
    },
  });
  assert.deepEqual(errorOf(withGetter), schema);
  const withSymbol = { ...base, [Symbol("extra")]: "1" };
  assert.deepEqual(errorOf(withSymbol), schema);
  const stringObject = { ...base };
  stringObject.lengthM = new String("8");
  assert.deepEqual(errorOf(stringObject), schema);
});

test("the core does not mutate its input", () => {
  const input = { ...base };
  const snapshot = JSON.stringify(input);
  const outcome = run(input);
  assert.equal(outcome.ok, true);
  assert.equal(JSON.stringify(input), snapshot);
  const bad = { ...base, depthM: "10.5" };
  const badSnapshot = JSON.stringify(bad);
  assert.equal(run(bad).ok, false);
  assert.equal(JSON.stringify(bad), badSnapshot);
});

test("display formatting: grouped integers, plain decimals, fill durations", () => {
  assert.equal(formatInteger(48000), "48,000");
  assert.equal(formatInteger(100000000), "100,000,000");
  assert.equal(formatInteger(0), "0");
  assert.equal(formatDecimal(23.56), "23.56");
  assert.equal(formatDecimal(1.5), "1.5");
  assert.equal(formatFillDuration(20, 0), "20:00");
  assert.equal(formatFillDuration(9, 5), "9:05");
  assert.equal(formatFillDuration(0, 59), "0:59");
});
